package com.ethk3.novaonepro.strategyv2;
import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import java.util.*;import java.nio.charset.StandardCharsets;
/** A complete census in ONE SQLite read statement on every supported API. No private transaction API or row sample. */
public final class ModelConsumptionCensusR30R1 {
 private ModelConsumptionCensusR30R1(){}
 static final String ORPHAN="SELECT count(*) FROM r30_model_call c LEFT JOIN r27_live_frozen f ON f.policy_hash=c.policy_hash AND f.target_ordinal=c.target_ordinal AND f.status='FROZEN' WHERE c.status='MATCHED' AND (f.policy_hash IS NULL OR c.frozen_at IS NOT f.frozen_at OR NOT EXISTS(SELECT 1 FROM r30_model_artifact a WHERE a.model_hash=c.model_hash) OR NOT EXISTS(SELECT 1 FROM r30_model_surface s WHERE s.target_ordinal=c.target_ordinal AND s.position=c.position AND s.model_hash=c.model_hash AND s.probability_hash=c.probability_hash))";
 static final String ROWS="SELECT 'T' AS kind,CAST((SELECT count(*) FROM r30_model_call WHERE status='MATCHED') AS TEXT) AS a,CAST((SELECT count(*) FROM r30_model_call WHERE status='BLOCKED') AS TEXT) AS b,CAST(("+ORPHAN+") AS TEXT) AS c,'' AS d UNION ALL SELECT 'P',s.policy_hash,s.spec_json,CAST((SELECT count(*) FROM r27_live_frozen f WHERE f.policy_hash=s.policy_hash AND f.status='FROZEN') AS TEXT),'' FROM r27_live_shadow s WHERE s.spec_json LIKE '%model_surface%' UNION ALL SELECT 'C',v.policy_hash,CAST(v.position AS TEXT),CAST(v.required_count AS TEXT),CAST(count(*) AS TEXT) FROM (SELECT DISTINCT c.policy_hash,c.position,c.required_count,f.target_ordinal FROM r30_model_call c JOIN r27_live_frozen f ON f.policy_hash=c.policy_hash AND f.target_ordinal=c.target_ordinal AND f.frozen_at=c.frozen_at WHERE c.status='MATCHED' AND f.status='FROZEN' AND c.position BETWEEN 1 AND 10 AND EXISTS(SELECT 1 FROM r30_model_artifact a WHERE a.model_hash=c.model_hash AND a.feature_abi='"+AtomNetSessionR30.ABI+"') AND EXISTS(SELECT 1 FROM r30_model_surface s WHERE s.target_ordinal=c.target_ordinal AND s.position=c.position AND s.model_hash=c.model_hash AND s.probability_hash=c.probability_hash)) v GROUP BY v.policy_hash,v.position,v.required_count UNION ALL SELECT 'B',reason,CAST(count(*) AS TEXT),'','' FROM r30_model_call WHERE status='BLOCKED' GROUP BY reason";
 public static String packedSql(){StringJoiner fields=new StringJoiner("||';'||");for(String field:new String[]{"kind","a","b","c","d"})fields.add("CASE WHEN "+field+" IS NULL THEN 'N' ELSE 'H'||hex(CAST("+field+" AS BLOB)) END");return "(SELECT CASE WHEN sum(length(encoded))>1048576 THEN 'OVERSIZE' ELSE group_concat(encoded,char(10)) END FROM (SELECT "+fields+" AS encoded FROM ("+ROWS+")))";}
 public static Map<String,Object> report(SQLiteDatabase db){try(Cursor c=db.rawQuery("SELECT "+packedSql(),null)){return parse(c.moveToFirst()?c.getString(0):null);}catch(RuntimeException e){Map<String,Object> out=new LinkedHashMap<>();out.put("status","UNKNOWN_SOURCE_READ_ERROR");out.put("reason",e.getClass().getSimpleName());return out;}}
 static String decode(String value){if(value.equals("N"))return null;if(!value.startsWith("H")||value.length()%2!=1)throw new IllegalArgumentException("CENSUS_ENCODING");byte[] bytes=new byte[(value.length()-1)/2];for(int i=0;i<bytes.length;i++){int a=Character.digit(value.charAt(1+i*2),16),b=Character.digit(value.charAt(2+i*2),16);if(a<0||b<0)throw new IllegalArgumentException("CENSUS_HEX");bytes[i]=(byte)(a*16+b);}return new String(bytes,StandardCharsets.UTF_8);}
 public static Map<String,Object> parse(String packed){Map<String,Object> out=new LinkedHashMap<>();out.put("snapshotScope","SINGLE_COMPLETE_SQLITE_SELECT_SHARED_WITH_REPORT_WHEN_EMBEDDED");out.put("quality","MODEL_CONSUMPTION_ONLY_NO_QUALITY_CLAIM");if(packed==null||packed.equals("OVERSIZE")){out.put("status","UNKNOWN_FULL_CENSUS_BYTE_BUDGET");out.put("reason","Complete denominator not materialized; original full tables retained. No bounded excerpt substituted.");return out;}try{long matched=-1,blocked=-1,orphan=-1,expected=0,applicable=0,invalid=0;Map<String,Integer> masks=new LinkedHashMap<>();Set<String> bad=new HashSet<>();List<String[]> calls=new ArrayList<>();List<Object> reasons=new ArrayList<>();for(String line:packed.split("\n")){String[] encoded=line.split(";",-1);if(encoded.length!=5)throw new IllegalArgumentException("CENSUS_ROW");String[] row=new String[5];for(int i=0;i<5;i++)row[i]=decode(encoded[i]);switch(row[0]){case "T":matched=Long.parseLong(row[1]);blocked=Long.parseLong(row[2]);orphan=Long.parseLong(row[3]);break;case "P":try{PolicySpecR27 p=PolicySpecR27.parse(row[2]);int mask=p.ast.modelPositions;masks.put(row[1],mask);expected+=Integer.bitCount(mask)*Long.parseLong(row[3]);}catch(RuntimeException malformed){bad.add(row[1]);}break;case "C":calls.add(row);break;case "B":Map<String,Object> reason=new LinkedHashMap<>();reason.put("reason",row[1]);reason.put("count",Long.parseLong(row[2]));reasons.add(reason);break;default:throw new IllegalArgumentException("CENSUS_KIND");}}
 for(String[] row:calls){Integer mask=masks.get(row[1]);int position=Integer.parseInt(row[2]),required=Integer.parseInt(row[3]);if(mask!=null&&position>=1&&position<=10&&(mask&(1<<(position-1)))!=0&&Integer.bitCount(mask)==required)applicable+=Long.parseLong(row[4]);}invalid=bad.size();if(matched<0||blocked<0||orphan<0)throw new IllegalArgumentException("CENSUS_TOTAL_MISSING");long missing=Math.max(0,expected-applicable),extra=Math.max(0,matched-applicable);out.put("matchedCalls",matched);out.put("blockedCalls",blocked);out.put("orphanCalls",orphan);out.put("expectedCallsFromActualAstPositions",expected);out.put("applicableMatchedCalls",applicable);out.put("missingCalls",missing);out.put("unexpectedOrRepeatedCalls",extra);out.put("invalidPolicySpecs",invalid);out.put("matchingRatio",expected>0&&invalid==0?applicable/(double)expected:null);out.put("blockedReasons",reasons);out.put("status",orphan+missing+extra>0?"FAIL":invalid>0?"UNKNOWN_INVALID_SOURCE":expected>0?"MATCHED":blocked>0?"BLOCKED":"INSUFFICIENT");return out;}catch(RuntimeException malformed){out.put("status","UNKNOWN_CENSUS_PARSE_ERROR");out.put("reason",malformed.getClass().getSimpleName());return out;}}
}
